// One place decides how a catalogue item is paid for, so review has one answer to audit
sealed interface Item {
  val sku: String
  // Consumed inside the app: store billing is mandatory
  data class Digital(override val sku: String, val storeProductId: String) : Item
  // Exists in the world: store billing is forbidden
  data class Physical(override val sku: String) : Item
  data class RealWorldService(override val sku: String) : Item
}

sealed interface Checkout {
  data class StoreBilling(val storeProductId: String) : Checkout // StoreKit / Play Billing
  data object OwnProcessor : Checkout                            // card sheet, wallet, invoice
  data class ExternalLink(val url: String) : Checkout            // web checkout, where allowed
}

fun checkoutFor(item: Item, policy: StorePolicy): Checkout = when (item) {
  is Item.Physical, is Item.RealWorldService -> Checkout.OwnProcessor
  is Item.Digital ->
    // Link-out eligibility depends on storefront and changes with every court ruling,
    // so it arrives from the server: a policy change is a config push, not a release.
    if (policy.externalLinkAllowed) Checkout.ExternalLink(policy.webCheckoutUrl(item.sku))
    else Checkout.StoreBilling(item.storeProductId)
}

// The two rejections this function exists to prevent:
// - a card form for Item.Digital because "the store takes 30%"  -> Apple 3.1.1 / Play Payments
// - IAP for Item.Physical because "it is one code path"          -> Apple 3.1.5

// Play has two product types (INAPP, SUBS); "consumable" is your decision, not the store's
private val consumableIds = setOf("coins_500", "coins_2000")

suspend fun settle(purchase: Purchase) {
  // PENDING (Ask to Buy, cash payment) is not money yet: never grant, never settle
  if (purchase.purchaseState != Purchase.PurchaseState.PURCHASED) return

  // The server verifies the token and credits the balance or writes the entitlement
  api.claim(purchase.purchaseToken, purchase.products.first())

  when {
    purchase.products.first() in consumableIds ->
      // consume = "delivered, let them buy it again". The token disappears afterwards,
      // so consuming before the credit lands loses the coins permanently.
      billing.consumePurchase(
        ConsumeParams.newBuilder().setPurchaseToken(purchase.purchaseToken).build()
      )

    !purchase.isAcknowledged ->
      // Non-consumable and subscription: acknowledge, or Play refunds it after 3 days
      billing.acknowledgePurchase(
        AcknowledgePurchaseParams.newBuilder().setPurchaseToken(purchase.purchaseToken).build()
      )
  }
}

