@main
struct ShopApp: App {
  // Started before any UI. Renewals, Ask to Buy approvals, promoted purchases and
  // buys made on another device all arrive here — never through the paywall callback.
  @State private var updates = Task.detached { await listen() }

  var body: some Scene { WindowGroup { RootView() } }
}

func listen() async {
  for await result in Transaction.updates { await settle(result) }
}

func drainAtLaunch() async {
  for await result in Transaction.unfinished { await settle(result) }
}

func settle(_ result: VerificationResult<Transaction>) async {
  // .verified proves Apple signed it — not that it is current, and not whose it is
  guard case .verified(let transaction) = result else { return }
  do {
    try await api.claim(originalId: transaction.originalID)  // server decides
    await entitlements.refresh()                             // the unlock happens here
    await transaction.finish()                               // only once the grant is durable
  } catch {
    // Leave it unfinished on purpose: StoreKit will redeliver it on the next launch
  }
}

func buy(_ product: Product, userId: UUID) async throws {
  switch try await product.purchase(options: [.appAccountToken(userId)]) {
  case .success(let verification): await settle(verification)
  case .pending: showAwaitingApproval()   // Ask to Buy: no money has moved
  case .userCancelled: break
  @unknown default: break
  }
  // The bug: unlock(product) right here, on .success alone. Unverified, and it is
  // blind to every purchase that does not return through this one call.
}

// The wrong way: settle in the client callback, hope the grant catches up
override fun onPurchasesUpdated(result: BillingResult, purchases: List<Purchase>?) {
  purchases?.forEach { p ->
    billing.acknowledgePurchase(                       // acknowledged...
      AcknowledgePurchaseParams.newBuilder().setPurchaseToken(p.purchaseToken).build()
    ) { }
    scope.launch { api.claim(p.purchaseToken) }        // ...and this may never arrive
  }
}

// The right way: the client only reports; the server verifies, grants, then acknowledges
override fun onPurchasesUpdated(result: BillingResult, purchases: List<Purchase>?) {
  if (result.responseCode != BillingResponseCode.OK) return
  purchases?.forEach { p ->
    if (p.purchaseState == Purchase.PurchaseState.PURCHASED) scope.launch { report(p) }
    // PENDING: do nothing. The 3-day clock has not started and no money has moved.
  }
}

private suspend fun report(p: Purchase) {
  // Retry this until it succeeds: an unreported purchase is a refund in three days.
  // queryPurchasesAsync on the next resume replays it, so a dropped call is survivable.
  val entitlement = api.claim(p.purchaseToken, p.products.first())  // server:
  //   1. purchases.subscriptionsv2.get / purchases.products.get   -> is it real and active
  //   2. upsert entitlement, keyed uniquely on the purchase token -> the grant
  //   3. purchases.subscriptions.acknowledge                      -> only now
  entitlements.emit(entitlement)                                    // then the UI
}

// What the client is allowed to know
data class Entitlement(
  val productId: String?,
  val status: Status,          // ACTIVE, GRACE, ON_HOLD, EXPIRED, NONE
  val expiresAt: Instant?,
  val willRenew: Boolean,
  val source: Source,          // APP_STORE, PLAY, WEB, PROMO
  val fetchedAt: Instant       // makes the offline policy expressible
) {
  // Grace period is still paid access, and the UI can say "fix your card" because
  // the status carries more than true/false.
  val unlocked: Boolean get() = status == Status.ACTIVE || status == Status.GRACE
}

class EntitlementRepository(private val api: Api, private val store: DataStore<Entitlement?>) {
  private val offlineGrace = 48.hours

  fun observe(): Flow<Entitlement> = store.data.map { it ?: Entitlement.none }

  suspend fun refresh() {
    runCatching { api.entitlement() }                       // server is the source of truth
      .onSuccess { store.updateData { _ -> it } }
      .onFailure {
        val cached = store.data.first() ?: return
        // Honour an already-active entitlement for a bounded window; never grant a new one
        if (Clock.System.now() - cached.fetchedAt > offlineGrace) {
          store.updateData { cached.copy(status = Status.EXPIRED) }
        }
      }
  }
}

