// Backend. The client is a courier: it carries an identifier, it does not assert anything.
suspend fun claim(userId: UserId, req: ClaimRequest): Entitlement = when (req.platform) {

  Platform.APP_STORE -> {
    // Signed JWS in, signed JWS out — verified against Apple's root by the library
    val status = appStore.getAllSubscriptionStatuses(req.originalTransactionId)
    val tx = status.latestTransaction()          // decoded + chain-verified
    entitlements.upsert(
      userId = userId,
      key = "apple:${tx.originalTransactionId}", // unique: a replay hits the constraint
      status = if (tx.revocationDate != null) EXPIRED else fromExpiry(tx.expiresDate),
      expiresAt = tx.expiresDate
    )
  }

  Platform.PLAY -> {
    val sub = play.purchases().subscriptionsv2()
      .get(packageName, req.purchaseToken).execute()
    // An upgrade issues a new token pointing at the old one. Follow it, or the same
    // person ends up holding two "active" subscriptions.
    sub.linkedPurchaseToken?.let { entitlements.supersede("play:$it") }
    val e = entitlements.upsert(
      userId = userId,
      key = "play:${req.purchaseToken}",
      status = fromState(sub.subscriptionState),
      expiresAt = sub.lineItems.last().expiryTime.toInstant()
    )
    // Acknowledge only after the grant is durable
    play.purchases().subscriptions().acknowledge(packageName, req.sku, req.purchaseToken, null)
    e
  }
}

// Play RTDN. The message is a doorbell: it tells you which token changed, nothing more.
suspend fun onRtdn(message: PubsubMessage) {
  // At-least-once delivery: the same messageId will arrive again
  if (!processed.insertIfAbsent(message.messageId)) return ack(message)

  val n = Json.decodeFromString<DeveloperNotification>(message.data.decodeToString())
  val token = n.subscriptionNotification?.purchaseToken
    ?: n.voidedPurchaseNotification?.purchaseToken
    ?: return ack(message)                       // testNotification and unknown kinds: ack anyway

  // Ignore n.notificationType for the decision — ask the API what is true right now
  val sub = play.purchases().subscriptionsv2().get(packageName, token).execute()

  db.transaction {
    val row = entitlements.forKey("play:$token")
    val fresh = sub.lineItems.last().expiryTime.toInstant()
    // Out-of-order delivery is normal: an older event must not undo a newer state
    if (row != null && row.expiresAt > fresh && row.status != REVOKED) return@transaction
    entitlements.upsert(
      key = "play:$token",
      status = fromState(sub.subscriptionState),  // absolute state, never a delta
      expiresAt = fresh
    )
    processed.commit(message.messageId)           // one transaction with the grant
  }
  ack(message)
}

// Restore, in the order the platform actually intends
func restore() async -> RestoreOutcome {
  // 1. The user tapped the button, so the expensive step is allowed: re-authenticate
  //    with the App Store. Never call this on launch — it prompts for a password.
  do { try await AppStore.sync() } catch { return .failed(error: error) }

  // 2. currentEntitlements is the source: everything the signed-in Apple Account owns.
  //    Consumables are absent by design — the balance is your server's problem.
  var claims: [UInt64] = []
  for await result in Transaction.currentEntitlements {
    guard case .verified(let transaction) = result else { continue }
    if transaction.revocationDate != nil { continue }        // refunded: not an entitlement
    claims.append(transaction.originalID)
  }

  // 3. A restore is a claim, not a grant. The server reconciles and may reject a
  //    transaction already bound to a different app account.
  let entitlement = try? await api.restore(originalIds: claims)

  // 4. Say something, always. "Nothing to restore" is a result, not a failure.
  guard let entitlement, entitlement.unlocked else {
    return .nothingFound(hint: "Check the Apple Account in Settings > [your name] > Media & Purchases")
  }
  return .restored(entitlement)
}

