// Purchase: attach your user id so the store echoes it back everywhere
fun buy(activity: Activity, details: ProductDetails, offerToken: String, userId: String) {
  val params = BillingFlowParams.newBuilder()
    .setProductDetailsParamsList(listOf(
      BillingFlowParams.ProductDetailsParams.newBuilder()
        .setProductDetails(details)
        .setOfferToken(offerToken)
        .build()))
    .setObfuscatedAccountId(hashed(userId))   // never the raw id; it reaches the store
    .build()
  billingClient.launchBillingFlow(activity, params)
}

// Server: the identifier is unique, and the first claimant owns it
suspend fun claim(userId: String, purchaseToken: String): ClaimResult {
  val sub = playApi.subscriptionsV2Get(packageName, purchaseToken)

  // A resubscribe or upgrade replaces an older token — retire it or it grants forever
  sub.linkedPurchaseToken?.let { old -> entitlements.retire(old) }

  val existing = entitlements.findByStoreRef(purchaseToken)
  if (existing != null && existing.userId != userId) return ClaimResult.OwnedByAnotherAccount

  entitlements.upsert(
    userId = userId,
    storeRef = purchaseToken,               // UNIQUE index lives here
    activeUntil = sub.lineItems.first().expiryTime,
    state = sub.subscriptionState
  )
  if (!sub.acknowledged) playApi.acknowledge(packageName, purchaseToken)
  return ClaimResult.Granted
}

// Ask first, then render — never assume the trial is available
func paywall(for product: Product, userId: UUID) async -> Paywall {
  guard let sub = product.subscription else { return .oneTime(product.displayPrice) }

  if await sub.isEligibleForIntroOffer, let intro = sub.introductoryOffer {
    return .trial(intro.period, then: product.displayPrice)   // store will honour it
  }
  if let winBack = sub.winBackOffers.first {                  // iOS 18+, lapsed subscribers
    return .winBack(winBack.displayPrice)
  }
  return .standard(product.displayPrice)
}

// A promotional offer is only valid with a signature your backend generates
func buyPromo(_ product: Product, offerID: String, userId: UUID) async throws {
  let signed = try await api.signOffer(productID: product.id, offerID: offerID)
  let signature = Product.SubscriptionOffer.Signature(
    keyID: signed.keyID, nonce: signed.nonce,
    timestamp: signed.timestamp, signature: signed.signature)

  _ = try await product.purchase(options: [
    .appAccountToken(userId),
    .promotionalOffer(offerID: offerID, signature: signature)
  ])
}

// The Android shape of the same bug: the paywall shows the trial, but the token
// passed to launchBillingFlow is the base plan's, so the charge is immediate.
// Pick the offer whose first pricing phase costs zero, or fall back deliberately.

// One vocabulary for both stores; the UI never sees a store-specific string
enum class SubState { ACTIVE, CANCELLED_ACTIVE, GRACE, HOLD, PAUSED, EXPIRED }

fun fromPlay(s: SubscriptionPurchaseV2): SubState = when (s.subscriptionState) {
  "SUBSCRIPTION_STATE_ACTIVE" ->
    if (s.lineItems.first().autoRenewingPlan?.autoRenewEnabled == true) SubState.ACTIVE
    else SubState.CANCELLED_ACTIVE
  "SUBSCRIPTION_STATE_IN_GRACE_PERIOD" -> SubState.GRACE   // access continues
  "SUBSCRIPTION_STATE_ON_HOLD" -> SubState.HOLD            // revoked, Play still retrying
  "SUBSCRIPTION_STATE_PAUSED" -> SubState.PAUSED
  "SUBSCRIPTION_STATE_CANCELED" -> SubState.CANCELLED_ACTIVE  // paid up until expiryTime
  else -> SubState.EXPIRED
}

// Access and messaging are two separate questions
fun hasAccess(state: SubState) =
  state == SubState.ACTIVE || state == SubState.CANCELLED_ACTIVE || state == SubState.GRACE

@Composable
fun SubscriptionBanner(state: SubState, endsOn: String, activity: Activity, billing: BillingClient) {
  when (state) {
    SubState.GRACE -> Banner("Update your payment method to keep your subscription") {
      billing.showInAppMessages(activity, InAppMessageParams.newBuilder()
        .addInAppMessageCategoryToShow(InAppMessageCategoryId.TRANSACTIONAL)
        .build()) { }
    }
    SubState.HOLD, SubState.EXPIRED -> Paywall(reason = state)
    SubState.CANCELLED_ACTIVE -> Banner("Your plan ends on $endsOn")   // not a paywall
    SubState.ACTIVE, SubState.PAUSED -> Unit
  }
}

// Price-increase consent arrives as a StoreKit message, not as a push
@MainActor
final class StoreMessages: ObservableObject {
  @Published var deferred: [Message] = []
  var isBusy = false                       // true during checkout or full-screen video

  func listen(in scene: UIWindowScene) async {
    for await message in Message.messages {
      guard message.reason == .priceIncreaseConsent || message.reason == .billingIssue
      else { continue }
      if isBusy { deferred.append(message) }            // defer, never discard
      else { try? message.display(in: scene) }
    }
  }

  func flush(in scene: UIWindowScene) {
    deferred.forEach { try? $0.display(in: scene) }
    deferred.removeAll()
  }
}

// Read the state so the UI can nudge before renewal stops
func increaseStatus(for product: Product) async -> String? {
  guard let statuses = try? await product.subscription?.status,
        case .verified(let info)? = statuses.first?.renewalInfo else { return nil }
  return info.priceIncreaseStatus == .pending ? "Confirm the new price to stay subscribed" : nil
}

