// One row, three writers. Every webhook converges here.
data class Entitlement(
  val userId: String, val product: String, val state: SubState,
  val activeUntil: Instant, val source: Source, val sourceRef: String
)

suspend fun onAppStoreNotification(payload: SignedPayload) {
  val tx = appleJws.verify(payload)                       // signature first, always
  val userId = users.byStoreRef(tx.originalTransactionId)
    ?: users.byAppAccountToken(tx.appAccountToken)
    ?: return deadLetters.park(tx)                        // a payment we cannot attribute yet
  upsert(
    userId = userId,
    source = Source.APP_STORE, sourceRef = tx.originalTransactionId,
    state = tx.toSubState(), activeUntil = tx.expiresDate
  )
}

