// The paywall asks the server first, so a cross-platform subscriber is never sold twice
suspend fun paywallOrManage(userId: String): PaywallState {
  val ent = entitlements.active(userId) ?: return PaywallState.Offer(products())
  return when (ent.source) {
    Source.PLAY -> PaywallState.AlreadySubscribed(manageUrl = PLAY_MANAGE_URL)
    Source.APP_STORE -> PaywallState.ManageOnIos       // Android cannot cancel it
    Source.STRIPE -> PaywallState.AlreadySubscribed(manageUrl = billingPortal(userId))
  }
}

import StoreKitTest

@MainActor
final class EntitlementTests: XCTestCase {
  var session: SKTestSession!

  override func setUp() async throws {
    session = try SKTestSession(configurationFileNamed: "Products")
    session.resetToDefaultState()
    session.clearTransactions()
    session.disableDialogs = true                 // no UI prompts in CI
    session.timeRate = .oneRenewalEveryMinute     // a year of renewals inside one test run
  }

  func testRefundRevokesAccess() async throws {
    let transaction = try await session.buyProduct(identifier: "pro.monthly")
    await store.reconcile()
    XCTAssertTrue(store.hasAccess)

    try session.refundTransaction(identifier: transaction.id)  // the case support actually files
    await store.reconcile()
    XCTAssertFalse(store.hasAccess, "a refunded transaction must not keep the entitlement")
  }

  func testBillingRetryKeepsAccessDuringGrace() async throws {
    _ = try await session.buyProduct(identifier: "pro.monthly")
    session.billingGracePeriodIsEnabled = true
    session.failTransactionsEnabled = true        // the renewal that cannot be charged
    await store.reconcile()
    XCTAssertTrue(store.hasAccess, "grace period keeps a failed renewal usable")
  }
}

