// Support path: an order id off the user's email receipt is enough
suspend fun recoverFromReceipt(orderId: String, userId: String): Recovery {
  val lookup = appStore.lookUpOrderId(orderId)          // GET /inApps/v1/lookup/{orderId}
  if (lookup.status != OrderLookupStatus.VALID) return Recovery.NotThisStoreAccount

  val tx = lookup.signedTransactions
    .map { appleJws.verify(it) }                        // never read an unverified payload
    .firstOrNull { it.revocationDate == null }
    ?: return Recovery.Refunded

  val owner = entitlements.userForStoreRef(tx.originalTransactionId)
  if (owner != null && owner != userId) return Recovery.SignedInToTheWrongAccount(owner)

  grant(userId, tx)          // the same idempotent path the webhook uses, keyed by that id
  return Recovery.Granted
}

// Failures are parked with their identifier, not logged and forgotten
suspend fun claim(storeRef: String, userId: String): ClaimResult = try {
  grant(userId, store.fetch(storeRef)); ClaimResult.Ok
} catch (e: Exception) {
  deadLetters.park(storeRef, userId, e.message)   // retried on a schedule, alarms on age
  ClaimResult.Deferred
}

// Goodwill has its own table: editing the store-derived row loses to the next DID_RENEW
suspend fun goodwill(userId: String, until: Instant, operatorId: String, reason: String) =
  manualGrants.insert(userId, until, operatorId, reason)

// Detection, so support is not the first signal
suspend fun sweepChargedButNotGranted(since: Instant) =
  appStore.notificationHistory(since)
    .filter { entitlements.byStoreRef(it.originalTransactionId) == null }
    .forEach { alerts.page("charged, no entitlement: ${it.originalTransactionId}") }

// Server assigns; the client only renders what the store says those ids cost
@Serializable
data class PaywallConfig(
  val variantId: String,                 // travels with the purchase claim
  val productIds: List<String>,
  val headline: String
)

suspend fun loadPaywall(): Paywall {
  val config = runCatching { api.paywallConfig() }.getOrDefault(BUNDLED_DEFAULT)

  val params = QueryProductDetailsParams.newBuilder()
    .setProductList(config.productIds.map {
      QueryProductDetailsParams.Product.newBuilder()
        .setProductId(it).setProductType(ProductType.SUBS).build()
    }).build()

  val details = billing.queryProductDetails(params).productDetailsList  // BL 7.1+ result type
  return Paywall(
    variantId = config.variantId,
    headline = config.headline,
    // The price comes from the store, formatted for this user's region
    tiers = details.map { d ->
      val offer = d.subscriptionOfferDetails!!.first()
      Tier(d.productId, offer.offerToken, offer.pricingPhases.pricingPhaseList.last().formattedPrice)
    }
  )
}

// The claim is where the arm gets recorded — renewals are attributed to it server-side
suspend fun onPurchased(purchase: Purchase, variantId: String) =
  api.claim(token = purchase.purchaseToken, variantId = variantId)
